CATALOG = {"A1": "Sample camera", "B2": "Sample microphone"}

def dispatch(name, args):
    if not isinstance(args, dict) or set(args) != {"sku"}:
        raise ValueError("Invalid arguments")
    sku = args["sku"]
    if not isinstance(sku, str) or sku not in CATALOG:
        raise ValueError("Unknown SKU")
    if name == "lookup":
        return {"item": CATALOG[sku]}
    if name == "prepare":
        return {"status": "draft_only", "sku": sku}
    raise PermissionError("Tool not allowed")

if __name__ == "__main__":
    assert dispatch("lookup", {"sku": "A1"})["item"] == "Sample camera"
    assert dispatch("prepare", {"sku": "B2"})["status"] == "draft_only"
    for name, args in [("execute", {"sku":"A1"}), ("lookup", {"sku":"bad"})]:
        try:
            dispatch(name, args)
        except (ValueError, PermissionError):
            pass
        else:
            raise AssertionError("Unsafe call accepted")
    print("4 tests passed")

import re

DOCUMENTS = {
    "D1": "Returns accepted within 14 days.",
    "D2": "Support is available Monday to Friday.",
    "D3": "Shipping costs depend on region."
}

def terms(text):
    return set(re.findall(r"\w+", text.lower())) - {"is","the","a","to","on","what"}

def retrieve(query):
    hits = [(len(terms(query) & terms(doc)), key, doc)
            for key, doc in DOCUMENTS.items()]
    hits.sort(reverse=True)
    score, key, doc = hits[0]
    if not score:
        return {"status": "insufficient_evidence", "sources": []}
    return {"status": "evidence", "sources": [key], "excerpt": doc}

if __name__ == "__main__":
    assert retrieve("returns")["sources"] == ["D1"]
    assert retrieve("shipping")["sources"] == ["D3"]
    assert retrieve("astronomy")["status"] == "insufficient_evidence"
    print("3 tests passed")

def planner(task):
    return {"action": "summarize", "text": task} if isinstance(task, str) and task.strip() else None

def worker(plan):
    if not plan or plan.get("action") != "summarize":
        return None
    return {"summary": plan["text"][:80]}

def reviewer(plan, output):
    return bool(plan and output and isinstance(output.get("summary"), str)
                and output["summary"] == plan["text"][:80])

def run(task):
    plan = planner(task)
    output = worker(plan)
    if not reviewer(plan, output):
        return {"status":"escalate"}
    return {"status":"ok", "output":output, "steps":3}

if __name__ == "__main__":
    assert run("Sample task")["status"] == "ok"
    assert run("")["status"] == "escalate"
    assert run(None)["status"] == "escalate"
    assert not reviewer(planner("hello"), {"summary":"invented"})
    print("4 tests passed")

import secrets

class LocalAgent:
    def __init__(self):
        self.catalog = {"A1": "Sample camera"}
        self.drafts = {}

    def lookup(self, sku):
        if sku not in self.catalog:
            return {"status":"not_found"}
        return {"status":"evidence", "source":sku, "item":self.catalog[sku]}

    def prepare(self, sku):
        if sku not in self.catalog:
            return {"status":"not_found"}
        if len(self.drafts) >= 20:
            return {"status":"limit"}
        key = secrets.token_hex(16)
        self.drafts[key] = sku
        return {"status":"approval_required", "draft_id":key, "sku":sku}

    def approve(self, key, human_approved=False):
        if human_approved is not True or key not in self.drafts:
            return {"status":"denied"}
        sku = self.drafts.pop(key)
        return {"status":"simulated_only", "sku":sku}

if __name__ == "__main__":
    agent = LocalAgent()
    assert agent.lookup("A1")["source"] == "A1"
    assert agent.lookup("B2")["status"] == "not_found"
    draft = agent.prepare("A1")
    assert agent.approve(draft["draft_id"])["status"] == "denied"
    assert agent.approve(draft["draft_id"], True)["status"] == "simulated_only"
    assert agent.approve(draft["draft_id"], True)["status"] == "denied"
    print("5 tests passed")
